// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }

    // fuzzed params: from (actor who is passed through to callee), v (value), and an array of to-addrs length
    function testFuzz_property(address from, uint256 v, uint256 tosLen) public {
        // keep tosLen in a reasonable range but allow 0 to be excluded by contract itself
        tosLen = bound(tosLen, 0, 8);

        // deploy a recording callee that exposes the exact function selector the contract calls
        Recorder rec = new Recorder();

        // build tos array of addresses: use distinct addresses derived from fuzzed 'from' and index
        address[] memory tos = new address[](tosLen);
        for (uint i = 0; i < tosLen; i++) {
            // create pseudo-random addresses from inputs so fuzzer can explore
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(from, v, i)))));
        }

        // Now call transfer and capture whether it reverts or returns
        bool ok;
        try c.transfer(from, address(rec), tos, v) returns (bool ret) {
            ok = ret; // record the returned boolean
        } catch {
            ok = false; // on revert, treat as not-ok
        }

        // GENERAL RULE asserted: whenever transfer completes (i.e., does not revert), the reference
        // implementation returns true. We observe completion by checking that c.transfer did not revert
        // and returned true. For the reference contract this must always hold; the mutant that returns
        // false on success will violate it for inputs where the call does not revert.

        // If the call reverted, we cannot assert about the return value; so require that the call completed.
        // Use the Recorder to check that the callee(s) were invoked as expected or that no-calls happened
        // when tosLen==0 (but contract itself requires tos.length>0 so revert then). We therefore only
        // assert when tosLen>0 and every external invocation succeeded; in that case ok must be true.

        if (tosLen > 0) {
            // Ensure recorder saw exactly tosLen calls and all succeeded
            // The Recorder increments counter on each invocation.
            uint256 called = rec.callCount();
            // If recorder saw fewer calls, the transfer reverted earlier; in that case we skip assertion by
            // requiring calls equal tosLen; this keeps the check to only the non-reverting executions.
            if (called == tosLen) {
                // For the correct contract, ok must be true for all such inputs.
                // The mutant that returns false for successful runs will make this assertion fail for some input.
                assertTrue(ok);
            }
        }
    }
}

// Minimal recording callee that exposes the exact signature transfer() will call via selector
contract Recorder {
    uint256 public callCounter;

    // The C contract calls selector of transferFrom(address,address,uint256)
    // declare that function so ABI-decoding works and we can record args
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        callCounter += 1;
        // record nothing else; succeed so that C's require(_s) passes in the reference path
        return true;
    }

    // allow test to read how many times it was called
    function callCount() external view returns (uint256) {
        return callCounter;
    }
}
